#!/usr/bin/env python
"""Embed the devsim certificates as Lean string literals (tier-2 fixtures read bytes, not files).

    python emit_lean_fixtures.py ../certs ../../../lean/Obend/Teeth/Hardware/DeviceCertificates.lean
"""
import os
import sys

PAIRS = [("a", "m0.50"), ("a", "m0.70"), ("b", "m0.50")]


def ident(tag, b):
    return f"{tag}_{b.replace('.', '_')}"


def main(certs, out):
    parts = ["module", "/-", "# Obend.Teeth.Hardware.DeviceCertificates — devsim's bytes for the sky130 diode (generated)", "",
             "Generated by `apps/sky130-diode/devsim/emit_lean_fixtures.py` from `apps/sky130-diode/certs/`, which",
             "`run_diode.py` writes. Do not edit; rerun the producer. Each pair is the object (`spec`) and the",
             "certificate (`cert`) of `devsim-dd1d@1` at one bias of one device: `a` is the p-well dose 1.3e13,",
             "`b` 2.6e13; `m0_50` is −0.5 V at the n⁺ contact (forward).", "-/",
             "public section", "", "namespace Obend.Teeth.Hardware.DeviceCertificates", ""]
    for tag, b in PAIRS:
        for kind in ("spec", "cert"):
            path = os.path.join(certs, f"{kind}_{tag}_{b}.json")
            with open(path) as f:
                s = f.read().strip()
            assert '"#' not in s
            parts.append(f"def {kind}_{ident(tag, b)} : String := r#\"{s}\"#")
            parts.append("")
    parts += ["end Obend.Teeth.Hardware.DeviceCertificates", "end", ""]
    with open(out, "w") as f:
        f.write("\n".join(parts))
    print(out, os.path.getsize(out), "bytes")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
